package zw.co.hyperfeeds.support;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController@RequestMapping("/livestock/questions")public class LivestockQuestionController{private final JdbcClient jdbc;private final LivestockGuidanceAssistant ai;public LivestockQuestionController(JdbcClient j,LivestockGuidanceAssistant a){jdbc=j;ai=a;}@PostMapping@ResponseStatus(HttpStatus.CREATED)UUID ask(Authentication a,@Valid@RequestBody Question q){UUID id=UUID.randomUUID();jdbc.sql("insert into livestock_questions(id,user_id,subject,question,status,ai_draft) values(:id,:u,:s,:q,'AWAITING_EXPERT',:draft)").param("id",id).param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).param("s",q.subject).param("q",q.question).param("draft",ai.draft(q.subject,q.question)).update();return id;}@GetMapping List<Map<String,Object>>mine(Authentication a){return jdbc.sql("select id,subject,question,status,expert_answer,created_at,answered_at from livestock_questions where user_id=:u order by created_at desc").param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).query().listOfRows();}@GetMapping("/review")@PreAuthorize("hasAnyRole('ANIMAL_HEALTH_EXPERT','ADMIN')")List<Map<String,Object>>review(){return jdbc.sql("select id,user_id,subject,question,status,ai_draft,created_at from livestock_questions where status='AWAITING_EXPERT' order by created_at").query().listOfRows();}@PutMapping("/{id}/answer")@PreAuthorize("hasAnyRole('ANIMAL_HEALTH_EXPERT','ADMIN')")@Transactional void answer(Authentication a,@PathVariable UUID id,@Valid@RequestBody Answer r){int n=jdbc.sql("update livestock_questions set expert_answer=:answer,status='ANSWERED',answered_by=:expert,answered_at=now() where id=:id and status='AWAITING_EXPERT'").param("answer",r.answer).param("expert",zw.co.hyperfeeds.identity.CurrentUser.id(a)).param("id",id).update();if(n==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Question is not awaiting an answer");UUID user=jdbc.sql("select user_id from livestock_questions where id=:id").param("id",id).query(UUID.class).single();jdbc.sql("insert into notifications(user_id,type,title,body,data) values(:u,'LIVESTOCK_ANSWER','Your livestock question was answered',:body,jsonb_build_object('questionId',:id))").param("u",user).param("body",r.answer).param("id",id.toString()).update();}record Question(@NotBlank@Size(max=200)String subject,@NotBlank@Size(max=5000)String question){}record Answer(@NotBlank@Size(max=10000)String answer){} }
